// Endereços desta instalação (detalhes em n8n/README.md). A URL do projeto não é segredo;
// a chave service_role fica só na credencial "Supabase".
const SUPABASE_URL = 'https://pcjyqwiuqphuiqgfvxqj.supabase.co';
// Quem recebe os avisos de falha de qualquer organização:
const EMAIL_SUPORTE = 'suporte@troque-este-endereco.com';

function rodou(nome) {
  try { return $(nome).isExecuted; } catch (e) { return false; }
}

let origem = 'manual';
let turno = null;
let token = null;
if (rodou('Disparo pelo Site')) {
  origem = 'site';
  token = String((($('Disparo pelo Site').first().json || {}).query || {}).token || '').replace(/[^A-Za-z0-9]/g, '');
  if (!token) return [];
} else if (rodou('Dia útil 12:00')) {
  origem = 'agendado';
  turno = '12';
} else if (rodou('Dia útil 07:00')) {
  origem = 'agendado';
  turno = '07';
}
return [{ json: { supabase_url: SUPABASE_URL.replace(/\/+$/, ''), suporte: EMAIL_SUPORTE, origem, turno, token } }];

// Uma linha por organização devolvida por robo_lote (o banco já decidiu quem entra).
const saida = [];
for (const item of $input.all()) {
  const j = item.json;
  const lista = Array.isArray(j) ? j : [j];
  for (const o of lista) if (o && o.organizacao_id) saida.push({ json: o });
}
return saida;

const org = $input.first().json;
const hoje = DateTime.now().setZone('America/Sao_Paulo');
const retroativos = Math.min(30, Math.max(1, Number(org.dias_retroativos) || 5));
const base = {
  dataDisponibilizacaoInicio: hoje.minus({ days: retroativos }).toISODate(),
  dataDisponibilizacaoFim: hoje.toISODate(),
  itensPorPagina: 100,
};
const consultas = [];
for (const m of org.monitoramentos || []) {
  const numero = String(m.numero || '').replace(/\D/g, '');
  if (m.tipo === 'oab' && numero && m.uf) consultas.push({ ...base, numeroOab: numero, ufOab: String(m.uf).toUpperCase() });
  else if (m.tipo === 'processo' && numero.length === 20) consultas.push({ ...base, numeroProcesso: numero });
}
return consultas.map(query => ({ json: { query } }));

const org = $('Uma organização por vez').first().json;
const PRAZO_PADRAO = Number(org.prazo_padrao_dias) || 15;

// <regra-vencimento> Mesma regra de web/src/domain/dias.ts (ADR-0002). O teste de paridade
// (web/src/domain/paridade-n8n.test.ts) lê este trecho: mude os dois lados juntos.
function criarRegra(feriadosLocais, considerarRecesso) {
  const locais = new Set(feriadosLocais);
  const FIXOS = ['01-01', '04-21', '05-01', '09-07', '10-12', '11-02', '11-15', '11-20', '12-25'];
  const santas = {};
  const paraData = iso => { const [a, m, d] = iso.split('-').map(Number); return new Date(Date.UTC(a, m - 1, d)); };
  const paraISO = data => data.toISOString().slice(0, 10);
  const somaDias = (data, n) => { const c = new Date(data); c.setUTCDate(c.getUTCDate() + n); return c; };
  function pascoa(y) {
    const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4;
    const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
    const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4;
    const l = (32 + 2 * e + 2 * i - h - k) % 7, m = Math.floor((a + 11 * h + 22 * l) / 451);
    const mes = Math.floor((h + l - 7 * m + 114) / 31), dia = ((h + l - 7 * m + 114) % 31) + 1;
    return new Date(Date.UTC(y, mes - 1, dia));
  }
  function sextaSanta(y) {
    if (!santas[y]) santas[y] = paraISO(somaDias(pascoa(y), -2));
    return santas[y];
  }
  function ehDiaUtil(iso) {
    const semana = paraData(iso).getUTCDay();
    if (semana === 0 || semana === 6) return false;
    if (iso === sextaSanta(Number(iso.slice(0, 4)))) return false;
    if (locais.has(iso)) return false;
    const md = iso.slice(5);
    if (considerarRecesso && (md >= '12-20' || md <= '01-20')) return false;
    return !FIXOS.includes(md);
  }
  function proximoDiaUtil(iso) {
    let x = somaDias(paraData(iso), 1);
    while (!ehDiaUtil(paraISO(x))) x = somaDias(x, 1);
    return paraISO(x);
  }
  function calcularVencimento(inicio, dias) {
    let x = ehDiaUtil(inicio) ? inicio : proximoDiaUtil(inicio);
    for (let c = 1; c < dias; c++) x = proximoDiaUtil(x);
    return x;
  }
  return { ehDiaUtil, proximoDiaUtil, calcularVencimento };
}
// </regra-vencimento>

const regra = criarRegra((org.feriados || []).map(f => String(f).slice(0, 10)), org.considerar_recesso !== false);

const POR_EXTENSO = { um: 1, uma: 1, dois: 2, duas: 2, 'três': 3, tres: 3, quatro: 4, cinco: 5, seis: 6, sete: 7, oito: 8, nove: 9, dez: 10, onze: 11, doze: 12, quinze: 15, vinte: 20, trinta: 30, quarenta: 40, sessenta: 60, noventa: 90 };

function detectarPrazo(texto) {
  const t = texto.toLowerCase();
  const achados = [];
  for (const m of t.matchAll(/(?:prazo|em|dentro de)\s+(?:\S+\s+){0,2}?(?:de\s+)?(\d{1,3})\s*(?:\([^)]{0,40}\))?\s*dias?\b/g)) {
    if (+m[1] >= 1 && +m[1] <= 365) achados.push(+m[1]);
  }
  for (const m of t.matchAll(/(?:prazo|em|dentro de)\s+(?:\S+\s+){0,2}?(?:de\s+)?(\S+)\s+dias?\b/g)) {
    if (POR_EXTENSO[m[1]]) achados.push(POR_EXTENSO[m[1]]);
  }
  const distintos = [...new Set(achados)].sort((a, b) => a - b);
  if (distintos.length === 1) return { dias: distintos[0], origem: 'Identificado no texto' };
  if (distintos.length > 1) {
    return { dias: distintos[0], origem: 'Mais de um prazo no texto (' + distintos.join(', ') + ' dias) - usado o menor, CONFERIR' };
  }
  const m = t.match(/(\d{1,3})\s*(?:\([^)]{0,40}\))?\s*horas/);
  if (m) return { dias: Math.max(1, Math.ceil(+m[1] / 24)), origem: 'Prazo em horas (' + m[1] + 'h) - CONFERIR' };
  return { dias: PRAZO_PADRAO, origem: 'Padrão (' + PRAZO_PADRAO + ' dias) - não identificado no texto' };
}

function parseData(v) {
  if (!v) return null;
  const s = String(v).slice(0, 10);
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(s);
  return m ? m[3] + '-' + m[2] + '-' + m[1] : null;
}
const DIACRITICOS = { acute: '\u0301', grave: '\u0300', tilde: '\u0303', circ: '\u0302', cedil: '\u0327', uml: '\u0308' };
const ENTIDADES = { nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", ordm: 'º', ordf: 'ª', sect: '§', deg: '°', ndash: '-', mdash: '-', laquo: '«', raquo: '»', ldquo: '"', rdquo: '"', lsquo: "'", rsquo: "'", hellip: '...' };
function limparHtml(s) {
  return String(s || '')
    .replace(/<(style|script|head)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&([A-Za-z])(acute|grave|tilde|circ|cedil|uml);/g, (_, l, d) => (l + DIACRITICOS[d]).normalize('NFC'))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(+n))
    .replace(/&([a-z]+);/gi, (m, e) => ENTIDADES[e.toLowerCase()] ?? m)
    .replace(/\s+/g, ' ')
    .trim();
}

const falhas = [];
const porId = new Map();
for (const item of $input.all()) {
  if (item.json.error) {
    const e = item.json.error;
    falhas.push(typeof e === 'string' ? e : (e.message || JSON.stringify(e)));
    continue;
  }
  const lista = Array.isArray(item.json.items) ? item.json.items : [];
  for (const c of lista) {
    const id = String(c.id ?? c.hash ?? '');
    if (id && !porId.has(id)) porId.set(id, c);
  }
}

const publicacoes = [];
for (const [id, c] of porId) {
  const teor = limparHtml(c.texto);
  const prazo = detectarPrazo(teor);
  const disponibilizacao = parseData(c.data_disponibilizacao || c.datadisponibilizacao || c.dataDisponibilizacao);
  const publicacao = disponibilizacao ? regra.proximoDiaUtil(disponibilizacao) : null;
  const inicio = publicacao ? regra.proximoDiaUtil(publicacao) : null;
  const vencimento = inicio ? regra.calcularVencimento(inicio, prazo.dias) : null;
  const partes = (c.destinatarios || []).map(x => x.nome + (x.polo ? ' (' + x.polo + ')' : '')).join('; ');
  // OABs intimadas, na ordem da publicação: o banco escolhe o responsável por elas.
  const advogados = (c.destinatarioadvogados || [])
    .map(d => (d && d.advogado) || d)
    .filter(Boolean)
    .map(a => ({ numero: String(a.numero_oab ?? a.numeroOab ?? ''), uf: String(a.uf_oab ?? a.ufOab ?? '') }));
  const precisaConferir = !vencimento || /CONFERIR|Padrão/.test(prazo.origem);

  publicacoes.push({
    djen_id: id,
    processo: c.numeroprocessocommascara || c.numero_processo || '',
    numero_processo: String(c.numero_processo || c.numeroprocessocommascara || '').replace(/\D/g, ''),
    tribunal: c.siglaTribunal || '',
    orgao: c.nomeOrgao || '',
    tipo: [c.tipoComunicacao, c.tipoDocumento].filter(Boolean).join(' / '),
    classe: String(c.nomeClasse || '').toUpperCase(),
    partes,
    advogados,
    prazo_dias: prazo.dias,
    origem_prazo: prazo.origem,
    data_disponibilizacao: disponibilizacao,
    data_publicacao: publicacao,
    inicio_prazo: inicio,
    vencimento,
    status: precisaConferir ? 'conferir' : 'pendente',
    link: c.link || 'https://comunica.pje.jus.br/',
    teor: teor.slice(0, 20000),
  });
}

publicacoes.sort((a, b) => String(a.vencimento || '9999').localeCompare(String(b.vencimento || '9999')));
return [{ json: { organizacao_id: org.organizacao_id, publicacoes, falhas } }];

const org = $('Uma organização por vez').first().json;
const { publicacoes, falhas } = $('Processar Publicações').first().json;
const gravacao = $input.first().json || {};
const mensagem = e => (typeof e === 'string' ? e : (e && (e.message || JSON.stringify(e))) || 'erro desconhecido');
const erro = gravacao.error ? mensagem(gravacao.error) : null;
const problemas = [...falhas, ...(erro ? ['Erro ao gravar prazos: ' + erro] : [])];
return [{ json: {
  org: org.organizacao_id,
  origem: org.origem,
  autor: org.autor || null,
  encontradas: publicacoes.length,
  novas: erro ? [] : (gravacao.ids || []),
  falhou: problemas.length > 0,
  detalhe: problemas.length ? problemas.join(' | ').slice(0, 2000) : null,
} }];

// Um e-mail por membro, com a janela de alerta e a preferência ("meus" ou "todos") de cada um.
// Buscar agora: só quem clicou. Turno das 12:00: só quem tem publicação nova.
const org = $('Uma organização por vez').first().json;
const cfg = $('Configurar').first().json;
const resultado = $('Resultado').first().json;
const resposta = $input.first().json || {};
const TZ = 'America/Sao_Paulo';
const hoje = DateTime.now().setZone(TZ).startOf('day');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const br = iso => (iso ? DateTime.fromISO(String(iso).slice(0, 10)).toFormat('dd/MM/yyyy') : '-');
const mensagem = e => (typeof e === 'string' ? e : (e && (e.message || JSON.stringify(e))) || 'erro desconhecido');

const problemas = resultado.detalhe ? [resultado.detalhe] : [];
if (resposta.error) problemas.push('Erro ao registrar a execução: ' + mensagem(resposta.error));
const falhou = resultado.falhou || Boolean(resposta.error);
const suporteValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(cfg.suporte) && !cfg.suporte.includes('troque-este-endereco');
const suporte = {
  avisar_suporte: falhou && suporteValido,
  suporte: cfg.suporte,
  assunto_suporte: '[Despert] Falha na execução de ' + org.nome + ' (' + org.origem + ')',
  html_suporte: '<p>Execução do robô falhou para a organização <b>' + esc(org.nome) + '</b> (' + esc(org.organizacao_id) + ').</p>'
    + '<pre style="white-space:pre-wrap">' + esc(problemas.join('\n').slice(0, 4000)) + '</pre>',
};

let destinatarios = Array.isArray(resposta.destinatarios) ? resposta.destinatarios : [];
if (org.origem === 'site') destinatarios = destinatarios.filter(d => d.user_id === org.autor);
if (cfg.turno === '12') destinatarios = destinatarios.filter(d => (d.novas || []).length > 0);

function situacao(d) {
  if (d < 0) return '<b style="color:#b00020">VENCIDO há ' + -d + ' dia(s)</b>';
  if (d === 0) return '<b style="color:#b00020">VENCE HOJE</b>';
  if (d === 1) return '<b style="color:#d35400">Vence amanhã</b>';
  return 'Em ' + d + ' dias';
}
const TH = 'style="text-align:left;padding:6px;border-bottom:2px solid #333;background:#f2f2f2"';
const TD = 'style="padding:6px;border-bottom:1px solid #ddd;vertical-align:top"';
const link = r => (r.link ? '<a href="' + esc(r.link) + '">abrir</a>' : '');
const tabela = (cabecalho, linhas) =>
  '<table style="border-collapse:collapse;width:100%"><tr>' + cabecalho.map(h => '<th ' + TH + '>' + h + '</th>').join('') + '</tr>' +
  linhas.map(cols => '<tr>' + cols.map(c => '<td ' + TD + '>' + c + '</td>').join('') + '</tr>').join('') + '</table>';

function avisoDaEtapa(d) {
  if (d.papel !== 'administrador') return '';
  if (resposta.etapa === 'aviso') {
    return '<div style="border:1px solid #d35400;background:#fff4e5;padding:10px;margin-bottom:16px">'
      + '<b>O pagamento do Despert está vencido.</b> A partir de ' + esc(br(resposta.leitura_em))
      + ' a organização fica em somente leitura, e em ' + esc(br(resposta.suspensa_em))
      + ' o robô para de buscar. Fale com o suporte para regularizar.</div>';
  }
  if (resposta.etapa === 'leitura') {
    return '<div style="border:1px solid #b00020;background:#fdecee;padding:10px;margin-bottom:16px">'
      + '<b>Organização em somente leitura.</b> O robô continua buscando até ' + esc(br(resposta.suspensa_em))
      + '. Fale com o suporte para reativar.</div>';
  }
  return '';
}

const itens = destinatarios.map(d => {
  const janela = Number(d.dias_alerta) || 7;
  const alertas = (d.alertas || [])
    .map(r => ({ ...r, _dias: Math.round(DateTime.fromISO(String(r.vencimento).slice(0, 10), { zone: TZ }).diff(hoje, 'days').days) }))
    .sort((a, b) => a._dias - b._dias);
  const novas = falhou && !(d.novas || []).length ? [] : (d.novas || []);
  const meus = d.escopo === 'meus';

  let html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">';
  html += '<h2>Despert - ' + esc(resposta.organizacao || org.nome) + ' - ' + hoje.toFormat('dd/MM/yyyy') + '</h2>';
  html += avisoDaEtapa(d);
  if (falhou) {
    html += '<div style="border:1px solid #b00020;background:#fdecee;padding:10px;margin-bottom:16px">'
      + '<b style="color:#b00020">Não foi possível concluir a consulta ao Diário (DJEN).</b> '
      + 'Verifique as publicações manualmente hoje em <a href="https://comunica.pje.jus.br/">comunica.pje.jus.br</a>.'
      + '<pre style="white-space:pre-wrap;font-size:12px">' + esc(problemas.join('\n').slice(0, 2000)) + '</pre></div>';
  }
  if (!alertas.length && !novas.length) {
    html += '<p>Nenhum prazo ' + (meus ? 'seu ' : '') + 'em alerta nos próximos ' + janela + ' dias e nenhuma publicação nova no Diário.</p>';
  } else {
    html += '<h3>Prazos ' + (meus ? 'seus ' : '') + 'em alerta (próximos ' + janela + ' dias e vencidos não cumpridos)</h3>';
    html += alertas.length
      ? tabela(['Situação', 'Vencimento', 'Processo', 'Tribunal', 'Tipo', 'Responsável', 'Link'],
          alertas.map(r => [situacao(r._dias), esc(br(r.vencimento)), esc(r.processo), esc(r.tribunal), esc(r.tipo), esc(r.responsavel), link(r)]))
      : '<p>Nenhum prazo pendente nessa janela.</p>';
    html += '<h3>Novas publicações no DJEN (' + novas.length + ')</h3>';
    html += novas.length
      ? tabela(['Vencimento', 'Prazo', 'Processo', 'Tribunal / Órgão', 'Tipo', 'Responsável', 'Trecho', 'Link'],
          novas.map(r => [
            '<b>' + esc(br(r.vencimento)) + '</b>',
            esc(r.prazo_dias) + ' dias<br><small>' + esc(r.origem_prazo) + '</small>',
            esc(r.processo),
            esc(r.tribunal) + '<br><small>' + esc(r.orgao) + '</small>',
            esc(r.tipo),
            esc(r.responsavel),
            '<small>' + esc(r.trecho) + '...</small>',
            link(r),
          ]))
      : '<p>Nenhuma publicação nova desde a última verificação.</p>';
  }
  html += '<p style="color:#777;font-size:12px;margin-top:24px">Vencimentos estimados automaticamente em dias úteis (CPC arts. 219, 220 e 224; Lei 11.419/2006, art. 4º). '
    + 'Sempre confira no processo. Marque o prazo como cumprido no painel para tirá-lo dos alertas. '
    + (meus ? 'Você recebe só os seus prazos; mude em Configurações.' : 'Você recebe os prazos de toda a organização; mude em Configurações.')
    + '</p></div>';

  const assunto = (falhou ? '[Prazos] FALHA na consulta ao Diário - verifique manualmente' : '[Prazos] '
    + (novas.length ? novas.length + ' nova(s) publicação(ões)' : 'Sem novas publicações'))
    + (alertas.length ? ' | ' + alertas.length + ' prazo(s) em alerta' : '')
    + (d.papel === 'administrador' && ['aviso', 'leitura'].includes(resposta.etapa) ? ' | Pagamento vencido' : '');

  return { json: { email: d.email, assunto, html, ...suporte } };
});

return itens.length ? itens : [{ json: { _nenhum: true, ...suporte } }];
